import SafariServices
import Foundation

/// Drop this into the Safari Web Extension target generated by
/// `xcrun safari-web-extension-converter` (replacing the generated handler),
/// and add `BrowserTarget.swift`, `ConfigStore.swift`, and `BrowserOpener.swift`
/// to the same extension target in Xcode.
final class SafariWebExtensionHandler: NSObject, NSExtensionRequestHandling {
    func beginRequest(with context: NSExtensionContext) {
        guard
            let item = context.inputItems.first as? NSExtensionItem,
            let userInfo = item.userInfo as? [String: Any],
            let message = userInfo[SFExtensionMessageKey] as? [String: Any]
        else {
            complete(context, payload: ["ok": false, "error": "BAD_REQUEST"])
            return
        }

        let type = message["type"] as? String ?? ""
        switch type {
        case "get_config":
            complete(context, payload: ConfigStore.payload())

        case "open_url":
            let urlString = message["url"] as? String ?? ""
            let targetId = (message["targetId"] as? String).flatMap { $0.isEmpty ? nil : $0 } ?? "last_used"
            let result = BrowserOpener.open(urlString: urlString, targetId: targetId)
            complete(context, payload: result)

        case "set_last_used":
            if let targetId = message["targetId"] as? String, !targetId.isEmpty {
                ConfigStore.setLastUsed(targetId: targetId)
                complete(context, payload: ["ok": true, "lastUsedTargetId": targetId])
            } else {
                complete(context, payload: ["ok": false, "error": "MISSING_TARGET_ID"])
            }

        default:
            complete(context, payload: ["ok": false, "error": "UNKNOWN_TYPE"])
        }
    }

    private func complete(_ context: NSExtensionContext, payload: [String: Any]) {
        let response = NSExtensionItem()
        response.userInfo = [SFExtensionMessageKey: payload]
        context.completeRequest(returningItems: [response], completionHandler: nil)
    }
}
